/**
 * Cleans the msg object and builds the entry structure
 * used throughout the POST flow.
 */
return {
    _msgid: msg._msgid,
    topic:  "new_message",
    entry: {
        id:        msg.payload.id,
        text:      msg.payload.text,
        timestamp: msg.payload.timestamp,
        author:    msg.payload.author,
        labels:    msg.payload.labels || [],
        metadata:  msg.metadata
    }
};

// Get all active connections from connections Object
const connections = global.get("parat_bridge.connections");
if (!connections) return null;
const active_connections = Object.values(connections).filter(c => c.active);

if (active_connections.length === 0) { return null; }

const messages = [];

// Loop over each active connection
active_connections.forEach(connection => {
    // loop over each client in connection
    Object.values(connection.clients).forEach(client => {

        // Find the target by excluding self using the unique identifier
        const target = Object.values(connection.clients)
            .find(c => c.identifier !== client.identifier);

        // Build the message and attach metadata
        messages.push({
            topic: client.client_system,   // routes to correct request builder
            metadata: {
                source: client,
                target: target,
                connection_name: connection.name
            }
        });
    });
});

// send each message one at a time
return [messages];

const sourceId = msg.metadata && msg.metadata.source && msg.metadata.source.identifier;
const connection_name = msg.metadata && msg.metadata.connection_name;
if (sourceId && connection_name) {
    const connections = global.get('parat_bridge.connections') || {};
    const conn = connections[connection_name];
    if (conn && conn.source_status && conn.source_status[sourceId]) {
        const status = conn.source_status[sourceId];
        const wasDown = status.down;
        // Oppdaterer in-memory direkte — IKKE kall global.set her,
        // det bryter msg.metadata.source-referansen som Filter-noden avhenger av
        status.consecutive_failures = 0;
        status.down = false;
        if (wasDown) {
            const entryQueue = global.get('parat_bridge.queue.entry_queue') || [];
            const now = Date.now();
            const sourceName = msg.metadata.source.name || sourceId;
            Object.values(conn.clients || {})
                .filter(c => c.identifier !== sourceId)
                .forEach((client, idx) => {
                    entryQueue.push({
                        entry: {
                            id: 'pb-att-' + (now + idx) + '-src-up-'
                                + Math.random().toString(36).slice(2, 5),
                            text: '✅ Tilkoblingen til ' + sourceName
                                + ' er gjenopprettet.',
                            timestamp: now + idx,
                            author: 'System-melding',
                            files: [], labels: [],
                            metadata: {
                                source: {
                                    client_system: 'parat_bridge',
                                    name: 'parat_bridge', identifier: 'parat_bridge'
                                },
                                target: client,
                                connection_name: connection_name
                            }
                        },
                        _retries: 0
                    });
                });
            global.set('parat_bridge.queue.entry_queue', entryQueue);
            node.log('Source restored: ' + sourceName + ' - notified ' + connection_name);
        }
        // Ingen global.set på connection-objektet — source_status er transient
    }
}
return msg;
